# Try rotate 90 degrees clockwise
test_input = [[3, 3, 6, 6, 6, 5, 6, 6, 3, 0, 4],
              [3, 3, 3, 3, 6, 6, 6, 6, 6, 6, 6],
              [6, 6, 3, 6, 6, 5, 6, 6, 3, 6, 4],
              [3, 6, 3, 3, 6, 5, 6, 1, 3, 6, 6]]

def rot90cw(grid):
    return list(zip(*grid[::-1]))

output = rot90cw(test_input)
print("Rotate 90 CW output:")
for row in output:
    print(list(row))

